"""CasADi model of a building generated by Trano with the ``mpc`` library.

Trano writes two artefacts for a building: a Modelica package whose ``<package>.building_mpc``
model is a flat, explicit RC ODE, and the :class:`trano.mpc.MPCModelInterface` listing the
states, inputs and parameters in the order of the CasADi vectors. :class:`RCModel` turns those
two artefacts into CasADi functions (continuous and discrete-time) with **symbolic parameters**,
which is what calibration, state estimation and MPC need.
"""

from __future__ import annotations

import fnmatch
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, field
from functools import cached_property
from pathlib import Path
from typing import TYPE_CHECKING, Any

import casadi as ca
import numpy as np
import pandas as pd
import rumoca
from trano.mpc import AnySystemSpec, InputRole, InputSpec, MPCModelInterface, RCModelType, StateSpec

if TYPE_CHECKING:
    from trano.mpc.estimation import EstimationSettings
    from trano.topology import Network

KELVIN = 273.15
STATE_BOUNDS = (243.15, 373.15)
"""Physical range of the temperatures states, used as bounds in the optimisation problems."""
STORAGE_TEMPERATURE_BOUNDS = (273.15, 373.15)
"""Physical range of a hot water tank temperature [K]."""
RESISTANCE_POWER = 3000.0
"""Electrical power of the resistance of a tank without heat pump [W]."""


@dataclass(frozen=True)
class ControlGroup:
    """Control inputs sharing one power limit (the compressor of a heat pump, a chiller)."""

    system: str
    indices: list[int]
    """Positions in the control vector."""
    max_power: float
    """Bound on the sum of the inputs [W]."""


@dataclass(frozen=True)
class StorageBand:
    """Soft temperature band of a hot water tank state."""

    system: str
    state_index: int
    lower: float
    upper: float


@dataclass(frozen=True)
class VehicleSpec:
    """What the controller needs to charge an electric vehicle: its state, input and sessions."""

    system: str
    state_index: int
    control_index: int
    capacity: float
    target_energy: float
    arrival_hour: float
    departure_hour: float
    weekend_present: bool

    def plugged_in(self, index: pd.DatetimeIndex) -> np.ndarray:
        """Whether the vehicle is at the charger at the start of each interval."""
        hours = np.asarray(index.hour + index.minute / 60, dtype=float)
        if self.departure_hour <= self.arrival_hour:
            away = (hours >= self.departure_hour) & (hours < self.arrival_hour)
        else:
            away = (hours >= self.departure_hour) | (hours < self.arrival_hour)
        if self.weekend_present:
            away &= np.asarray(index.dayofweek < 5)
        return ~away

    def departures(self, index: pd.DatetimeIndex, time_step: float) -> np.ndarray:
        """Whether the vehicle leaves during each interval (the target energy applies at its end)."""
        start = self.plugged_in(index)
        end = self.plugged_in(index + pd.Timedelta(seconds=time_step))
        return np.asarray(start & ~end, dtype=bool)


class ModelError(ValueError):
    """The Modelica package and the interface do not describe the same model."""


@dataclass(frozen=True)
class DiscreteDynamics:
    """Zero-order-hold discretisation ``x_next = F(x, u, d, p)`` of the RC model (RK4)."""

    step: ca.Function
    time_step: float
    substeps: int

    def __call__(self, x: Any, u: Any, d: Any, p: Any) -> Any:  # noqa: ANN401
        return self.step(x, u, d, p)


@dataclass(frozen=True)
class AffineDynamics:
    """Exact discrete-time affine form ``x_next = A x + Bu u + Bd d + c`` for fixed parameters.

    The RC models are linear in the states and the inputs, so the RK4 map is exactly affine and
    can be used by a Kalman filter without any approximation.
    """

    A: np.ndarray
    Bu: np.ndarray
    Bd: np.ndarray
    c: np.ndarray
    time_step: float

    def __call__(self, x: np.ndarray, u: np.ndarray, d: np.ndarray) -> np.ndarray:
        return np.asarray(self.A @ x + self.Bu @ u + self.Bd @ d + self.c, dtype=float)


@dataclass
class RCModel:
    """A Trano RC building model as CasADi functions with symbolic parameters.

    Build it from the files written by ``trano create-model house.yaml mpc``
    (:meth:`from_files`), directly from the YAML description (:meth:`from_yaml`, which calls
    Trano) or from a Trano network (:meth:`from_network`).

    The vectors follow the interface order: ``x`` the states, ``u`` the control inputs
    (``<zone>_QHea``), ``d`` the disturbances (``TOut``, ``HSol_*``, ``<zone>_QInt``) and ``p``
    the parameters. :attr:`parameters` holds the current (initial or calibrated) values.
    """

    interface: MPCModelInterface
    source: str
    parameters: np.ndarray
    _rhs: ca.Function = field(repr=False)
    base_dir: Path | None = None

    # ----------------------------------------------------------------- constructors
    @classmethod
    def from_source(cls, source: str, interface: MPCModelInterface, base_dir: Path | None = None) -> RCModel:
        export = rumoca.Session().loads(source, model=interface.model).to_casadi()
        _check_interface(interface, export)
        return cls(
            interface=interface,
            source=source,
            parameters=np.array(interface.parameter_values, dtype=float),
            base_dir=base_dir,
            _rhs=export.rhs,
        )

    @classmethod
    def from_files(cls, modelica: Path | str, interface: Path | str | None = None) -> RCModel:
        """Load ``house.mo`` and ``house.mpc.json`` (defaults to the json next to the ``.mo``)."""
        modelica_path = Path(modelica)
        interface_path = Path(interface) if interface else modelica_path.with_suffix(".mpc.json")
        return cls.from_source(
            modelica_path.read_text(), MPCModelInterface.read(interface_path), base_dir=modelica_path.parent
        )

    @classmethod
    def from_network(cls, network: Network, base_dir: Path | None = None) -> RCModel:
        from trano.mpc import network_interface

        return cls.from_source(network.model(), network_interface(network), base_dir=base_dir)

    @classmethod
    def from_yaml(
        cls,
        path: Path | str,
        model_type: RCModelType = RCModelType.r3c2,
        settings: EstimationSettings | None = None,
        name: str | None = None,
    ) -> RCModel:
        """Generate the model with Trano from a building description (``.yaml`` or ``.json``).

        ``settings`` are the :class:`trano.mpc.EstimationSettings` used by Trano to derive the
        initial RC parameters from the geometry and constructions.
        """
        from trano.data_models.conversion import convert_network
        from trano.elements.library.library import Library

        path = Path(path).resolve()
        library = Library.from_configuration("mpc").model_copy(update={"rc_model_type": model_type})
        network = convert_network(name or _package_name(path.stem), path, library=library)
        if settings is not None:
            from trano.mpc import network_interface, rc_building_from_network

            building = rc_building_from_network(network, model_type=model_type, settings=settings)
            runnable = network_interface(network)
            interface = building.interface(network.name).model_copy(
                update={"weather_file": runnable.weather_file, "runnable_model": None}
            )
            return cls.from_source(building.to_modelica(network.name), interface, base_dir=path.parent)
        return cls.from_network(network, base_dir=path.parent)

    def write(self, directory: Path | str, stem: str | None = None) -> tuple[Path, Path]:
        """Write ``<stem>.mo`` and ``<stem>.mpc.json`` (with the current parameters)."""
        directory = Path(directory)
        directory.mkdir(parents=True, exist_ok=True)
        stem = stem or self.interface.package
        modelica_path = directory / f"{stem}.mo"
        modelica_path.write_text(self.source)
        return modelica_path, self.portable_interface().write(directory / f"{stem}.mpc.json")

    # ----------------------------------------------------------------- names and indices
    @property
    def name(self) -> str:
        return str(self.interface.model)

    @property
    def state_names(self) -> list[str]:
        return list(self.interface.state_names)

    @property
    def input_names(self) -> list[str]:
        return list(self.interface.input_names)

    @property
    def parameter_names(self) -> list[str]:
        return list(self.interface.parameter_names)

    @cached_property
    def control_names(self) -> list[str]:
        return [signal.name for signal in self.interface.controls]

    @cached_property
    def controls(self) -> list[InputSpec]:
        return list(self.interface.controls)

    @cached_property
    def systems(self) -> list[AnySystemSpec]:
        return list(self.interface.systems)

    def system(self, name: str) -> AnySystemSpec:
        return self.interface.system(name)

    @cached_property
    def disturbance_names(self) -> list[str]:
        return [signal.name for signal in self.interface.disturbances]

    @cached_property
    def zone_names(self) -> list[str]:
        return [zone.name for zone in self.interface.zones]

    @cached_property
    def comfort_states(self) -> list[str]:
        """Indoor air temperature state of each zone (the comfort variable)."""
        return [zone.indoor_temperature for zone in self.interface.zones]

    @cached_property
    def comfort_indices(self) -> list[int]:
        return [self.state_names.index(name) for name in self.comfort_states]

    @cached_property
    def measured_states(self) -> list[str]:
        """States with a sensor: the zone air temperatures and the storage states (tank, batteries)."""
        storages = [state.name for state in self.interface.states if state.system is not None]
        return self.comfort_states + storages

    @cached_property
    def measured_indices(self) -> list[int]:
        return [self.state_names.index(name) for name in self.measured_states]

    @property
    def n_measured(self) -> int:
        return len(self.measured_states)

    # ----------------------------------------------------------------- systems and carriers
    def _control_positions(self, predicate: Any) -> list[int]:  # noqa: ANN401
        return [position for position, signal in enumerate(self.controls) if predicate(signal)]

    @cached_property
    def zone_heating_indices(self) -> list[int]:
        """Position of the heating input of each zone in the control vector (zone order)."""
        return [self.control_names.index(zone.heating_input) for zone in self.interface.zones]

    @cached_property
    def heat_control_indices(self) -> list[int]:
        """Thermal control inputs (ideal heating, costed at the tariff price)."""
        return self._control_positions(lambda signal: signal.carrier == "heat")

    @cached_property
    def gas_control_indices(self) -> list[int]:
        return self._control_positions(lambda signal: signal.carrier == "gas")

    @cached_property
    def discharge_control_indices(self) -> list[int]:
        """Battery discharging inputs: electricity delivered to the meter."""
        discharging = {system.discharge_input for system in self.systems if system.kind == "battery"}
        return self._control_positions(lambda signal: signal.name in discharging)

    @cached_property
    def consumption_control_indices(self) -> list[int]:
        """Electrical control inputs drawn from the meter (heat pumps, chillers, tanks, charging)."""
        discharging = set(self.discharge_control_indices)
        electrical = self._control_positions(lambda signal: signal.carrier == "electricity")
        return [position for position in electrical if position not in discharging]

    @cached_property
    def generation_indices(self) -> list[int]:
        """Positions of the PV generation inputs in the disturbance vector."""
        return [
            position
            for position, signal in enumerate(self.interface.disturbances)
            if signal.source is not None and signal.source.kind == "photovoltaic"
        ]

    @property
    def has_meter(self) -> bool:
        """Whether electricity is exchanged with the grid (electrical inputs or PV)."""
        return bool(self.consumption_control_indices or self.discharge_control_indices or self.generation_indices)

    @cached_property
    def gas_efficiencies(self) -> np.ndarray:
        """Efficiency of the boiler behind each gas control input (``gas_control_indices`` order)."""
        efficiencies = {}
        for system in self.systems:
            if system.kind == "boiler":
                for name in system.inputs:
                    efficiencies[name] = system.efficiency
        return np.array([efficiencies.get(self.control_names[i], 1.0) for i in self.gas_control_indices])

    @cached_property
    def control_groups(self) -> list[ControlGroup]:
        """Compressor limits shared by the inputs of a heat pump (zones and tanks) or a chiller."""
        groups = []
        for system in self.systems:
            if system.kind == "heat_pump":
                names = list(system.inputs) + list(system.tank_inputs)
            elif system.kind == "chiller":
                names = list(system.inputs)
            else:
                continue
            indices = [self.control_names.index(name) for name in names if name in self.control_names]
            if indices:
                groups.append(ControlGroup(system=system.name, indices=indices, max_power=system.max_electrical_power))
        return groups

    @cached_property
    def storage_bands(self) -> list[StorageBand]:
        return [
            StorageBand(
                system=system.name,
                state_index=self.state_names.index(system.state),
                lower=system.min_temperature,
                upper=system.set_temperature,
            )
            for system in self.systems
            if system.kind == "dhw_tank"
        ]

    @cached_property
    def vehicles(self) -> list[VehicleSpec]:
        return [
            VehicleSpec(
                system=system.name,
                state_index=self.state_names.index(system.state),
                control_index=self.control_names.index(system.charge_input),
                capacity=system.capacity,
                target_energy=system.target_soc * system.capacity,
                arrival_hour=system.arrival_hour,
                departure_hour=system.departure_hour,
                weekend_present=system.weekend_present,
            )
            for system in self.systems
            if system.kind == "ev_charger"
        ]

    @cached_property
    def _system_limits(self) -> dict[str, float]:
        """Upper bound [W] of the control inputs owned by a system."""
        limits: dict[str, float] = {}
        for system in self.systems:
            limits |= _system_input_limits(system)
        return limits

    def control_bounds(self) -> tuple[np.ndarray, np.ndarray]:
        """Lower and upper bound of each control input [W] from the interface (design powers, converters)."""
        upper = np.full(self.n_controls, np.inf)
        lower = np.zeros(self.n_controls)
        design = {zone.heating_input: zone.design_heating_power for zone in self.interface.zones}
        limits = self._system_limits
        for position, signal in enumerate(self.controls):
            if signal.name in limits:
                upper[position] = limits[signal.name]
            elif design.get(signal.name) is not None:
                upper[position] = float(design[signal.name])
        if not np.all(np.isfinite(upper)):
            missing = [self.control_names[i] for i in np.flatnonzero(~np.isfinite(upper))]
            raise ModelError(f"The interface gives no power bound for the controls {missing}.")
        return lower, upper

    def state_bounds(self) -> tuple[np.ndarray, np.ndarray]:
        """Physical bounds of the states: temperatures, tank temperatures and stored energies."""
        lower = np.full(self.n_states, STATE_BOUNDS[0])
        upper = np.full(self.n_states, STATE_BOUNDS[1])
        for system in self.systems:
            if system.kind == "dhw_tank":
                index = self.state_names.index(system.state)
                lower[index], upper[index] = STORAGE_TEMPERATURE_BOUNDS
            elif system.kind == "battery":
                index = self.state_names.index(system.state)
                lower[index], upper[index] = system.min_soc * system.capacity, system.max_soc * system.capacity
            elif system.kind == "ev_charger":
                index = self.state_names.index(system.state)
                lower[index], upper[index] = 0.0, system.capacity
        return lower, upper

    def state_spec(self, name: str) -> StateSpec:
        return next(state for state in self.interface.states if state.name == name)

    @cached_property
    def control_indices(self) -> list[int]:
        return [i for i, signal in enumerate(self.interface.inputs) if signal.role == InputRole.control]

    @cached_property
    def disturbance_indices(self) -> list[int]:
        return [i for i, signal in enumerate(self.interface.inputs) if signal.role == InputRole.disturbance]

    @property
    def n_states(self) -> int:
        return len(self.state_names)

    @property
    def n_controls(self) -> int:
        return len(self.control_indices)

    @property
    def n_disturbances(self) -> int:
        return len(self.disturbance_indices)

    @property
    def n_parameters(self) -> int:
        return len(self.parameter_names)

    @property
    def n_zones(self) -> int:
        return len(self.zone_names)

    @cached_property
    def max_heating_power(self) -> np.ndarray:
        """Upper bound of the heating input of each zone [W]: the design heating power of a thermal
        input, the compressor limit of the heat pump for an electrical one."""
        _, upper = self.control_bounds()
        return np.array([upper[index] for index in self.zone_heating_indices], dtype=float)

    @property
    def initial_state(self) -> np.ndarray:
        return np.array(self.interface.initial_state, dtype=float)

    @property
    def weather_path(self) -> Path | None:
        """Weather file of the runnable model, resolved against the directory of the model."""
        if self.interface.weather_file is None:
            return None
        path = Path(self.interface.weather_file)
        if path.is_absolute() or self.base_dir is None:
            return path
        return (self.base_dir / path).resolve()

    # ----------------------------------------------------------------- parameters
    @property
    def parameter_values(self) -> dict[str, float]:
        return dict(zip(self.parameter_names, self.parameters.tolist(), strict=True))

    def parameter(self, name: str) -> float:
        return float(self.parameters[self.parameter_names.index(name)])

    def select_parameters(self, patterns: Iterable[str]) -> list[str]:
        """Parameter names matching any of the ``fnmatch`` patterns (e.g. ``"*_Ci"``, ``"H_*"``)."""
        patterns = list(patterns)
        return [name for name in self.parameter_names if any(fnmatch.fnmatch(name, pattern) for pattern in patterns)]

    def with_parameters(self, values: Mapping[str, float] | Sequence[float] | np.ndarray) -> RCModel:
        """Copy of the model with other parameter values (a mapping of names or a full vector)."""
        if isinstance(values, Mapping):
            unknown = set(values) - set(self.parameter_names)
            if unknown:
                raise KeyError(f"Unknown parameters: {sorted(unknown)}")
            vector = self.parameters.copy()
            for name, value in values.items():
                vector[self.parameter_names.index(name)] = float(value)
        else:
            vector = np.asarray(values, dtype=float).reshape(-1)
            if vector.size != self.n_parameters:
                raise ModelError(f"Expected {self.n_parameters} parameters, got {vector.size}.")
        return RCModel(
            interface=self.interface, source=self.source, parameters=vector, base_dir=self.base_dir, _rhs=self._rhs
        )

    def calibrated_interface(self) -> MPCModelInterface:
        """The interface with the current parameter values (e.g. after calibration)."""
        parameters = [
            specification.model_copy(update={"value": float(value)})
            for specification, value in zip(self.interface.parameters, self.parameters, strict=True)
        ]
        return self.interface.model_copy(update={"parameters": parameters})

    def portable_interface(self) -> MPCModelInterface:
        """:meth:`calibrated_interface` with the weather file as an absolute path, if it exists."""
        interface = self.calibrated_interface()
        weather = self.weather_path
        if weather is not None and weather.exists():
            interface = interface.model_copy(update={"weather_file": str(weather)})
        return interface

    # ----------------------------------------------------------------- dynamics
    @cached_property
    def continuous(self) -> ca.Function:
        """``xdot = f(x, u, d, p)`` with the control and disturbance inputs separated."""
        x = ca.MX.sym("x", self.n_states)
        u = ca.MX.sym("u", self.n_controls)
        d = ca.MX.sym("d", self.n_disturbances)
        p = ca.MX.sym("p", self.n_parameters)
        return ca.Function(
            "f", [x, u, d, p], [self._rhs(0, x, self.stack_inputs(u, d), p)], ["x", "u", "d", "p"], ["xdot"]
        )

    def stack_inputs(self, u: Any, d: Any) -> Any:  # noqa: ANN401
        """Interleave control and disturbance vectors into the input vector of the Modelica model."""
        signals: list[Any] = [None] * len(self.input_names)
        for position, index in enumerate(self.control_indices):
            signals[index] = u[position]
        for position, index in enumerate(self.disturbance_indices):
            signals[index] = d[position]
        return ca.vertcat(*signals)

    def split_inputs(self, inputs: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        """Inverse of :meth:`stack_inputs` for a ``(n_inputs, N)`` array."""
        return inputs[self.control_indices], inputs[self.disturbance_indices]

    def stable_substeps(self, time_step: float, safety: float = 4.0) -> int:
        """RK4 sub-steps keeping ``h * max|eigenvalue| <= 2.5 / safety`` at the current parameters."""
        eigenvalues = np.linalg.eigvals(self.jacobian())
        fastest = float(np.max(np.abs(eigenvalues))) if eigenvalues.size else 0.0
        return max(1, int(np.ceil(time_step * fastest * safety / 2.5)))

    def jacobian(self, parameters: np.ndarray | None = None) -> np.ndarray:
        """Continuous-time state matrix ``df/dx`` (constant: the model is linear in the states)."""
        x = ca.MX.sym("x", self.n_states)
        u = ca.DM.zeros(self.n_controls)
        d = ca.DM.zeros(self.n_disturbances)
        p = self.parameters if parameters is None else parameters
        jac = ca.Function("state_jacobian", [x], [ca.jacobian(self.continuous(x, u, d, p), x)])
        return np.array(jac(ca.DM.zeros(self.n_states)), dtype=float)

    def discrete(self, time_step: float, substeps: int | None = None) -> DiscreteDynamics:
        """RK4 discretisation with zero-order-hold inputs; ``p`` stays symbolic."""
        substeps = substeps or self.stable_substeps(time_step)
        x = ca.MX.sym("x", self.n_states)
        u = ca.MX.sym("u", self.n_controls)
        d = ca.MX.sym("d", self.n_disturbances)
        p = ca.MX.sym("p", self.n_parameters)
        f = self.continuous
        h = time_step / substeps
        x_next = x
        for _ in range(substeps):
            k1 = f(x_next, u, d, p)
            k2 = f(x_next + h / 2 * k1, u, d, p)
            k3 = f(x_next + h / 2 * k2, u, d, p)
            k4 = f(x_next + h * k3, u, d, p)
            x_next = x_next + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)
        step = ca.Function("F", [x, u, d, p], [x_next], ["x", "u", "d", "p"], ["x_next"])
        return DiscreteDynamics(step=step, time_step=time_step, substeps=substeps)

    def linearization(self, time_step: float, substeps: int | None = None) -> ca.Function:
        """``(x, u, d) -> (x_next, A)``: the discrete map and its state Jacobian at the current parameters.

        Exact for the (linear) envelope; for a heat pump the heat is bilinear in the electrical
        power and the emitter or tank temperature, so the Jacobian depends on the operating point
        (extended Kalman filter).
        """
        dynamics = self.discrete(time_step, substeps)
        x = ca.MX.sym("x", self.n_states)
        u = ca.MX.sym("u", self.n_controls)
        d = ca.MX.sym("d", self.n_disturbances)
        x_next = dynamics(x, u, d, self.parameters)
        return ca.Function(
            "linearization", [x, u, d], [x_next, ca.jacobian(x_next, x)], ["x", "u", "d"], ["x_next", "A"]
        )

    def affine(self, time_step: float, substeps: int | None = None) -> AffineDynamics:
        """Affine form of :meth:`discrete` at the current parameters, linearised at zero inputs.

        Exact for the envelope models (linear in the states and the inputs); approximate when a
        heat pump makes the dynamics bilinear, use :meth:`linearization` then.
        """
        dynamics = self.discrete(time_step, substeps)
        x = ca.MX.sym("x", self.n_states)
        u = ca.MX.sym("u", self.n_controls)
        d = ca.MX.sym("d", self.n_disturbances)
        x_next = dynamics(x, u, d, self.parameters)
        matrices = ca.Function(
            "affine", [x, u, d], [ca.jacobian(x_next, x), ca.jacobian(x_next, u), ca.jacobian(x_next, d), x_next]
        )
        zeros = [ca.DM.zeros(n) for n in (self.n_states, self.n_controls, self.n_disturbances)]
        A, Bu, Bd, c = (np.array(matrix, dtype=float) for matrix in matrices(*zeros))
        return AffineDynamics(A=A, Bu=Bu, Bd=Bd, c=c.reshape(-1), time_step=time_step)

    def simulate(
        self,
        x0: np.ndarray | Sequence[float],
        controls: np.ndarray,
        disturbances: np.ndarray,
        time_step: float,
        parameters: np.ndarray | None = None,
        substeps: int | None = None,
    ) -> np.ndarray:
        """Open-loop simulation: ``(n_states, N + 1)`` trajectory for ``(n_controls, N)`` controls."""
        controls = np.atleast_2d(np.asarray(controls, dtype=float))
        disturbances = np.atleast_2d(np.asarray(disturbances, dtype=float))
        steps = controls.shape[1]
        if disturbances.shape != (self.n_disturbances, steps) or controls.shape[0] != self.n_controls:
            raise ModelError(
                f"Expected controls ({self.n_controls}, N) and disturbances ({self.n_disturbances}, N), "
                f"got {controls.shape} and {disturbances.shape}."
            )
        dynamics = self.discrete(time_step, substeps)
        p = self.parameters if parameters is None else np.asarray(parameters, dtype=float)
        trajectory = dynamics.step.mapaccum(steps)(np.asarray(x0, dtype=float), controls, disturbances, p)
        return np.hstack([np.asarray(x0, dtype=float).reshape(-1, 1), np.array(trajectory, dtype=float)])

    def simulate_frame(
        self, x0: np.ndarray | Sequence[float], inputs: pd.DataFrame, parameters: np.ndarray | None = None
    ) -> pd.DataFrame:
        """:meth:`simulate` with a time-indexed frame of inputs; returns the states on the same index."""
        from mpctrano.data import time_step_of

        time_step = time_step_of(inputs.index)
        controls = inputs[self.control_names].to_numpy(dtype=float).T[:, :-1]
        disturbances = inputs[self.disturbance_names].to_numpy(dtype=float).T[:, :-1]
        states = self.simulate(x0, controls, disturbances, time_step, parameters=parameters)
        return pd.DataFrame(states.T, index=inputs.index, columns=self.state_names)


def _system_input_limits(system: AnySystemSpec) -> dict[str, float]:
    """Upper bound [W] of the control inputs of one system."""
    if system.kind == "heat_pump":
        return dict.fromkeys(list(system.inputs) + list(system.tank_inputs), system.max_electrical_power)
    if system.kind == "chiller":
        return dict.fromkeys(system.inputs, system.max_electrical_power)
    if system.kind == "boiler":
        return dict.fromkeys(system.inputs, system.max_heating_power)
    if system.kind == "battery":
        return {system.charge_input: system.max_charge_power, system.discharge_input: system.max_discharge_power}
    if system.kind == "ev_charger":
        return {system.charge_input: system.max_charge_power}
    resistance = system.kind == "dhw_tank" and system.heat_pump is None
    return {system.heating_input: RESISTANCE_POWER} if resistance else {}


def _package_name(stem: str) -> str:
    sanitized = "".join(character if character.isalnum() or character == "_" else "_" for character in stem)
    return sanitized if sanitized[:1].isalpha() else f"m_{sanitized}"


def _check_interface(interface: MPCModelInterface, export: Any) -> None:  # noqa: ANN401
    pairs = (
        ("states", interface.state_names, list(export.state_names)),
        ("inputs", interface.input_names, list(export.input_names)),
        ("parameters", interface.parameter_names, list(export.parameter_names)),
    )
    for kind, expected, actual in pairs:
        if expected != actual:
            raise ModelError(f"The {kind} of the interface differ from the Modelica model: {expected} != {actual}.")


def celsius(kelvin: np.ndarray | float) -> np.ndarray | float:
    return kelvin - KELVIN


def kelvin(celsius_value: np.ndarray | float) -> np.ndarray | float:
    return celsius_value + KELVIN
